"""Authoritative Cortex configuration for CAREER-01--CAREER-03."""

from .care_lessons import ADAPTATION_POLICY


def _screen(lesson_id, purpose, activity_type, title, **configuration):
    configuration.update({"lesson_id": lesson_id, "instructional_purpose": purpose, "adaptive_delivery": ADAPTATION_POLICY})
    return {"title": title, "type": activity_type, "configuration": configuration}


def _choice(lesson_id, purpose, title, question, choices, answer, correct, retry):
    return _screen(lesson_id, purpose, "interactive", title, task_template="multiple_choice", question=question, choices=choices, answer=answer, correct_feedback=correct, retry_feedback=retry)


